function validate([colors, queries]) {
  const n = colors.length;
  if (n < 4 || n > 50000) return 'colors needs 4 to 5 * 10^4 tiles.';
  if (colors.some(c => c !== 0 && c !== 1)) return 'Each colour is 0 or 1.';
  if (queries.length < 1 || queries.length > 50000) return 'queries needs 1 to 5 * 10^4 entries.';
  for (const query of queries) {
    if (query[0] === 1) {
      if (query.length !== 2 || !Number.isInteger(query[1]) || query[1] < 3 || query[1] > n - 1) return 'A [1, size] query needs 3 <= size <= colors.length - 1.';
    } else if (query[0] === 2) {
      if (query.length !== 3 || !Number.isInteger(query[1]) || query[1] < 0 || query[1] >= n) return 'A [2, index, color] query needs 0 <= index < colors.length.';
      if (query[2] !== 0 && query[2] !== 1) return 'A [2, index, color] query needs a colour of 0 or 1.';
    } else return 'Each query starts with 1 or 2.';
  }
  return null;
}

