function numberOfAlternatingGroups(colors, queries) {
  const n = colors.length;
  const marks = new Array(n + 1).fill(0);
  const runCount = new Array(n + 1).fill(0);
  const runTiles = new Array(n + 1).fill(0);
  let breaks = 0;
  let highBit = 1;
  while (highBit * 2 <= n) highBit *= 2;
  const update = (tree, index, delta) => {
    for (let i = index; i <= n; i += i & -i) tree[i] += delta;
  };
  const prefix = (tree, index) => {
    let total = 0;
    for (let i = index; i > 0; i -= i & -i) total += tree[i];
    return total;
  };
  const findBreak = k => {
    let pos = 0;
    for (let step = highBit; step > 0; step >>= 1) {
      if (pos + step <= n && marks[pos + step] < k) {
        pos += step;
        k -= marks[pos];
      }
    }
    return pos;
  };
  const mark = (edge, delta) => {
    update(marks, edge + 1, delta);
    breaks += delta;
  };
  const gap = (from, to) => (to - from + n) % n || n;
  const addRun = (length, sign) => {
    update(runCount, length, sign);
    update(runTiles, length, sign * length);
  };
  const flipEdge = edge => {
    const sign = colors[edge] === colors[(edge + 1) % n] ? 1 : -1;
    if (sign < 0) mark(edge, -1);
    if (breaks === 0) {
      addRun(n, sign);
    } else {
      const below = prefix(marks, edge);
      const prev = findBreak(below > 0 ? below : breaks);
      const next = findBreak(below < breaks ? below + 1 : 1);
      addRun(gap(prev, next), -sign);
      addRun(gap(prev, edge), sign);
      addRun(gap(edge, next), sign);
    }
    if (sign > 0) mark(edge, 1);
  };
  for (let edge = 0; edge < n; edge++) {
    if (colors[edge] === colors[(edge + 1) % n]) flipEdge(edge);
  }
  const answer = [];
  for (const query of queries) {
    if (query[0] === 1) {
      const size = query[1];
      const runs = prefix(runCount, n) - prefix(runCount, size - 1);
      const tiles = prefix(runTiles, n) - prefix(runTiles, size - 1);
      answer.push(breaks === 0 ? n : tiles - (size - 1) * runs);
    } else {
      const [, index, color] = query;
      if (colors[index] === color) continue;
      colors[index] = color;
      flipEdge((index + n - 1) % n);
      flipEdge(index);
    }
  }
  return answer;
}

