function numberOfAlternatingGroups(colors, queries) {
  // Apply recolours directly and test every starting tile for each count query.
  const tiles = [...colors];
  const n = tiles.length;
  const answer = [];
  for (const query of queries) {
    if (query[0] === 2) {
      tiles[query[1]] = query[2];
      continue;
    }
    let count = 0;
    for (let start = 0; start < n; start++) {
      let alternates = true;
      for (let step = 1; step < query[1] && alternates; step++) {
        alternates = tiles[(start + step) % n] !== tiles[(start + step - 1) % n];
      }
      if (alternates) count++;
    }
    answer.push(count);
  }
  return answer;
}

