function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? pick(1800, 2000) : pick(4, 9);
  const total = large ? 2000 : pick(1, 10);
  // Mostly alternating colours with a few defects, so that long alternating runs exist.
  const noise = [0, 0.05, 0.2, 0.6][pick(0, 3)];
  const colors = [];
  for (let i = 0; i < n; i++) colors.push(rand() < noise ? pick(0, 1) : i % 2);
  const count = () => [1, large && rand() < 0.6 ? pick(3, 40) : pick(3, n - 1)];
  const queries = [];
  for (let i = 0; i < total; i++) {
    if (rand() < (large ? 0.7 : 0.5)) {
      queries.push(count());
    } else {
      // Repair (the alternating colour) or damage the tile; it may already have that colour.
      const index = pick(0, n - 1);
      queries.push([2, index, rand() < 0.5 ? index % 2 : 1 - (index % 2)]);
    }
  }
  // Make sure there is something to report.
  if (!queries.some(query => query[0] === 1)) queries[queries.length - 1] = count();
  return [colors, queries];
}
